<?php get_header(); while ( have_posts() ) : the_post(); $universities = get_the_terms( get_the_ID(), 'course_university' ); $instructors = get_the_terms( get_the_ID(), 'course_instructor' ); ?>
<main><section class="courseHero"><div class="wrap"><div><span class="idx"><b>01</b><i>COURSE DETAIL</i></span><small><?php echo esc_html( $universities && ! is_wp_error( $universities ) ? $universities[0]->name : '' ); ?></small><h1><?php the_title(); ?></h1><p><?php echo esc_html( $instructors && ! is_wp_error( $instructors ) ? $instructors[0]->name : '' ); ?> · <?php echo esc_html( get_post_meta( get_the_ID(), '_estudy24_lessons', true ) ); ?> درس · <?php echo esc_html( get_post_meta( get_the_ID(), '_estudy24_level', true ) ); ?></p><span class="price"><b><?php echo esc_html( get_post_meta( get_the_ID(), '_estudy24_price', true ) ); ?> ر.س</b></span></div><img src="<?php echo esc_url( estudy24_course_image_url( get_the_ID() ) ); ?>" alt="<?php the_title_attribute(); ?>"></div></section><section class="block"><div class="wrap prose"><?php the_content(); ?></div></section></main>
<?php endwhile; get_footer(); ?>
